#include <stdio.h>

static void print_row(unsigned long offset, const unsigned char *row, int count)
{
    printf("%08lx  ", offset);
    for (int i = 0; i < 16; i++) {
        if (i < count) printf("%02x ", row[i]);
        else printf("   ");
    }
    printf(" |");
    for (int i = 0; i < count; i++) {
        putchar(row[i] >= 32 && row[i] <= 126 ? row[i] : '.');
    }
    printf("|\n");
}

int main(void)
{
    unsigned char row[16];
    int count = 0;
    unsigned long offset = 0;
    int c;
    while ((c = fgetc(stdin)) != EOF) {
        row[count++] = (unsigned char)c;
        if (count == 16) {
            print_row(offset, row, count);
            offset += 16;
            count = 0;
        }
    }
    if (count > 0) {
        print_row(offset, row, count);
        offset += (unsigned long)count;
    }
    printf("%08lx\n", offset);
    return 0;
}
